const res = $input.first()?.json || {};
const refreshed = Number(res.refreshed || res.count || 0);
const failed = Number(res.failed || res.errors || 0);
return [{ json: {
  ok: res.ok !== false,
  refreshed: refreshed,
  failed: failed,
  note: res.ok === false ? 'prism-token-refresh function not reachable yet (deploy from docs/SUPABASE_PRISM_V2_PROMPTS.md and set PRISM_SUPABASE_URL + credential)' : 'refresh cycle complete',
  diagnostics: { requestId: 'ref-' + ($execution.id || 'na') + '-' + Date.now(), workflow: 'prism-18-token-refresh-health' }
} }];
